<?php
use App\Models\{Faq,User,WebsiteSetting}; use Illuminate\Foundation\Testing\RefreshDatabase; uses(RefreshDatabase::class); beforeEach(function(){file_put_contents(storage_path('app/installed'),now()->toIso8601String());WebsiteSetting::create(['site_name'=>'Test','site_url'=>'https://example.test','timezone'=>'UTC']);}); afterEach(fn()=>@unlink(storage_path('app/installed'))); test('faq renders only visible escaped content and accessible disclosure',function(){Faq::factory()->create(['question'=>'Private question?']);Faq::factory()->published()->create(['question'=>'Visible question?','answer'=>'<script>unsafe</script>']);$this->get('/faq')->assertSuccessful()->assertSee('Visible question?')->assertDontSee('Private question?')->assertSee('aria-expanded',false)->assertSee('aria-controls',false)->assertDontSee('<script>unsafe</script>',false)->assertSee('FAQPage');}); test('faq admin requires authentication',function(){$this->get('/content/faqs')->assertRedirect('/login');});
